class MobPageAdhocMenuItemsAdditionalProperties extends MobPageMenuItemsAdditionalProperties
{

    MobDocumentTypeId           documentType;
    MobDocumentContentSubject   contentType;
    boolean						refreshOnSuccess;
    MobPageID                   pageId;

}

Method.Source:
public boolean parmRefreshOnSuccess(boolean	_refreshOnSuccess = refreshOnSuccess)
{
    refreshOnSuccess = _refreshOnSuccess;
    return refreshOnSuccess;
}

public MobDocumentContentSubject parmContentType(MobDocumentContentSubject _contentType = contentType)
{
    contentType = _contentType;

    return contentType;
}

public MobDocumentTypeId parmDocumentType(MobDocumentTypeId _documentType = documentType)
{
    documentType = _documentType;

    return documentType;
}

public MobPageID parmNavigateTo(MobPageID _pageId = pageId)
{
    pageId = _pageId;

    return pageId;
}

public Map getparameters()
{
    Map ret = super();
    ret.insert('/onSuccessfulPost/navigateTo',[pageId]);
    ret.insert('/onSuccessfulPost/refreshOnSuccess',[refreshOnSuccess]);
    ret.insert('/documentName', [documentType]);
    ret.insert('/registrationType', [contentType]);
    return ret;
}
